const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const root = path.resolve(__dirname, '..')
const pagina = fs.readFileSync(path.join(root, 'app/orcamento-rapido/page.tsx'), 'utf8')
const cliente = fs.readFileSync(path.join(root, 'components/clientes/RascunhosOrcamentoCliente.tsx'), 'utf8')
const identificacao = fs.readFileSync(path.join(root, 'app/clientes/identificar/page.tsx'), 'utf8')
const cliente360 = fs.readFileSync(path.join(root, 'components/clientes/Cliente360DashboardV2.tsx'), 'utf8')
const offline = fs.readFileSync(path.join(root, 'lib/offlineFila.ts'), 'utf8')
const envio = fs.readFileSync(path.join(root, 'lib/orcamentos.ts'), 'utf8')

assert.match(pagina, /const abrirNovo = !idValido/, 'Abre pedido novo quando nao pediu rascunho explicitamente')
assert.match(pagina, /obterRascunho<RascunhoOrcamentoRapido>\(idAtivo\)/, 'Carrega apenas rascunho escolhido')
assert.match(pagina, /:pedido:\$\{uuidv4\(\)\}/, 'Novo pedido possui ID exclusivo')
assert.match(pagina, /clienteIdOrigem: clienteIdOrigem \|\| new URLSearchParams/, 'Rascunho vinculado ao cliente ja selecionado')
assert.match(pagina, /void salvarRascunho\(rascunhoIdAtivo, montarRascunhoAtual\(\)\)/, 'Erro de validacao salva rascunho imediatamente')
assert.match(pagina, /const rascunhosVisiveis = clienteIdOrigem[\s\S]+?r\.dados\?\.clienteIdOrigem === clienteIdOrigem/, 'Lista somente rascunhos do cliente atual')
assert.match(cliente, /r\.dados\?\.clienteIdOrigem === clienteId/, 'Cliente 360 vincula rascunhos por ID, nao por nome')
assert.match(identificacao, /<RascunhosOrcamentoCliente clienteId=\{clienteSelecionado\.id\}/, 'Cliente identificado mostra os rascunhos')
assert.match(cliente360, /<RascunhosOrcamentoCliente clienteId=\{cliente\.id\}/, 'Cliente 360 mostra os rascunhos')
assert.match(offline, /export async function listarRascunhos/, 'Rascunho preservado sem exclusao de outros')
assert.match(pagina, /if \(it\.itemTipo === 'medida_padrao'\)[\s\S]+?!it\.produtoId && !descricaoMedidaPadrao\(it\)/, 'Catalogo OU nome digitado para medida padrao')
assert.match(pagina, /onChange\(\{tipo:'outro',tipoOutroTexto:texto,produtoNome:texto,produtoId:null,precoUnit:null,modoOrigem:'manual'\}\)/, 'Texto manual fica salvo no pedido')
assert.match(envio, /descricaoMedidaPadrao\(it\) \|\| null/, 'Servidor preserva texto manual')
assert.match(envio, /const preco_unit = it\.modoOrigem === 'produto' && it\.precoUnit != null \? it\.precoUnit : null/, 'Preco do item digitado permanece pendente')
console.log('PASSOU: pedido novo, rascunho vinculado ao cliente, medida padrao selecionada/digitada e precificacao pendente')
